// 2026-10-23, ТЗ «Маркетплейс — редизайн и медиа» (П-2): единый набор векторных значков Маркетплейса вместо эмодзи.
// Геометрия — Material Design Icons (Templarian/MaterialDesign, @mdi/svg 7.4.47, лицензия Apache 2.0), поле 24x24, как в Themes/AppIcons.axaml;
// общий AppIcons.axaml не правится (по ТЗ), значки лежат здесь строками path-data и разбираются при первом обращении.
public static class MarketplaceIcons
{
    /// <summary>Значок, который показывается для неизвестного ключа.</summary>
    public const string FallbackKey = "information-outline";

    private static readonly Dictionary<string, Geometry> Cache = new();

    /// <summary>Геометрия значка по ключу (MarketplaceItem.IconKey / MarketplaceBenefit.IconKey, имя MDI без префикса);
    /// null — ключ пустой (витрина рисует прежний IconGlyph); неизвестный непустой ключ — «information-outline».</summary>
    public static Geometry? Get(string? key)
    {
        if (string.IsNullOrWhiteSpace(key))
            return null;
        key = key.Trim();
        lock (Cache)
        {
            if (Cache.TryGetValue(key, out var cached))
                return cached;
            if (!Paths.TryGetValue(key, out var data))
                data = Paths[FallbackKey];
            var geo = Geometry.Parse(data);
            Cache[key] = geo;
            return geo;
        }
    }

    /// <summary>Есть ли в наборе такой ключ (для самопроверки контента).</summary>
    public static bool Has(string? key) => !string.IsNullOrWhiteSpace(key) && Paths.ContainsKey(key.Trim());

    /// <summary>Готовый PathIcon со значком; цвет задаёт вызывающий (Foreground).</summary>
    public static PathIcon Icon(string? key, double size)
    {
        var icon = new PathIcon
        {
            Width = size,
            Height = size,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            IsHitTestVisible = false,
        };
        icon.Data = Get(string.IsNullOrWhiteSpace(key) ? FallbackKey : key);
        return icon;
    }

